1	# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
2	# Deploys the Datadog Agent to a Kubernetes cluster using the official Helm chart.
3	# ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
4	
5	# ---------------------------------------------------------------------------------------------------------------------
6	# SET TERRAFORM REQUIREMENTS FOR RUNNING THIS MODULE
7	# ---------------------------------------------------------------------------------------------------------------------
8	
9	terraform {
10	  required_version = ">= 1.3.0, < 2.0"
11	
12	  required_providers {
13	    helm = {
14	      source  = "hashicorp/helm"
15	      version = "~> 2.0"
16	    }
17	    kubernetes = {
18	      source  = "hashicorp/kubernetes"
19	      version = "~> 2.0"
20	    }
21	  }
22	}
23	
24	locals {
25	  apm_rules = file("${path.module}/processing-rules/${var.env}/apm.json")
26	  log_rules = file("${path.module}/processing-rules/${var.env}/rules.json")
27	  nowrds_instance = var.enable_nowrds_monitoring ? (<<-EON
28	    - dbm: true
29	      ssl: allow
30	      host: "%%env_NOWRDS_HOST%%"
31	      port: "%%env_NOWRDS_PORT%%"
32	      username: "%%env_NOWRDS_USERNAME%%"
33	      password: "%%env_NOWRDS_PASSWORD%%"
34	      collect_schemas:
35	        enabled: true
36	      database_autodiscovery:
37	        enabled: true
38	      tags:
39	        - "dbinstanceidentifier:%%env_NOWRDS_INSTANCE_NAME%%"
40	        - "env:%%env_DD_ENV%%"
41	  EON
42	  ) : null
43	}
44	# ---------------------------------------------------------------------------------------------------------------------
45	# CREATE A NAMESPACE
46	# ---------------------------------------------------------------------------------------------------------------------
47	resource "kubernetes_namespace" "this" {
48	  count = var.create_namespace ? 1 : 0
49	  metadata {
50	    name = var.namespace
51	  }
52	}
53	
54	resource "kubernetes_config_map" "datadog_processing_rules" {
55	  metadata {
56	    name = "rules-config"
57	    namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
58	  }
59	  data = {
60	    //"apm"  = local.apm_rules
61	    "apm" = file("${path.module}/processing-rules/${var.env}/apm.json")
62	    //"logs" = local.log_rules
63	    "logs" = file("${path.module}/processing-rules/${var.env}/rules.json")
64	  }
65	  depends_on = [kubernetes_namespace.this]
66	}
67	
68	resource "kubernetes_manifest" "external-secret-dd-api-key" {
69	  manifest = {
70	    apiVersion = "external-secrets.io/v1"
71	    kind       = "ExternalSecret"
72	    metadata = {
73	      name      = "datadog-api-key"
74	      namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
75	    }
76	    spec = {
77	      refreshInterval = "1h0m0s"
78	      secretStoreRef = {
79	        name = "vault"
80	        kind = "ClusterSecretStore"
81	      }
82	      target = {
83	        name           = "datadog-api-key"
84	        creationPolicy = "Owner"
85	      }
86	      data = [{
87	        secretKey = "api-key"
88	        remoteRef = {
89	          key      = "saas/infrastructure/datadog-api-key"
90	          property = "apiKey"
91	        }
92	      }]
93	    }
94	  }
95	}
96	
97	resource "kubernetes_manifest" "external-secret-dd-api-token" {
98	  manifest = {
99	    apiVersion = "external-secrets.io/v1"
100	    kind       = "ExternalSecret"
101	    metadata = {
102	      name      = "datadog-clusteragent-token"
103	      namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
104	    }
105	    spec = {
106	      refreshInterval = "1h0m0s"
107	      secretStoreRef = {
108	        name = "vault"
109	        kind = "ClusterSecretStore"
110	      }
111	      target = {
112	        name           = "datadog-clusteragent-token"
113	        creationPolicy = "Owner"
114	      }
115	      data = [{
116	        secretKey = "token"
117	        remoteRef = {
118	          key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
119	          property = "token"
120	        }
121	      }]
122	    }
123	  }
124	}
125	
126	resource "kubernetes_manifest" "external-secret" {
127	  count = (var.enable_mrds_monitoring || var.enable_nowrds_monitoring) ? 1 : 0
128	
129	  manifest = {
130	    apiVersion = "external-secrets.io/v1"
131	    kind       = "ExternalSecret"
132	    metadata = {
133	      name      = "datadog-env"
134	      namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
135	    }
136	    spec = {
137	      refreshInterval = "1h0m0s"
138	      secretStoreRef = {
139	        name = "vault"
140	        kind = "ClusterSecretStore"
141	      }
142	      target = {
143	        name           = "datadog-env"
144	        creationPolicy = "Owner"
145	      }
146	      data = concat(var.enable_mrds_monitoring ? [
147	        {
148	          secretKey = "MRDS_HOST"
149	          remoteRef = {
150	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
151	            property = "rds-host"
152	          }
153	        },
154	        {
155	          secretKey = "MRDS_PORT"
156	          remoteRef = {
157	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
158	            property = "rds-port"
159	          }
160	        },
161	        {
162	          secretKey = "MRDS_USERNAME"
163	          remoteRef = {
164	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
165	            property = "rds-username"
166	          }
167	        },
168	        {
169	          secretKey = "MRDS_PASSWORD"
170	          remoteRef = {
171	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
172	            property = "rds-password"
173	          }
174	        },
175	        {
176	          secretKey = "MRDS_REGION"
177	          remoteRef = {
178	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
179	            property = "rds-region"
180	          }
181	        },
182	        {
183	          secretKey = "MRDS_INSTANCE_NAME"
184	          remoteRef = {
185	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
186	            property = "rds-instance"
187	          }
188	        },
189	      ] : [], var.enable_nowrds_monitoring ? [
190	        {
191	          secretKey = "NOWRDS_HOST"
192	          remoteRef = {
193	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
194	            property = "NOWRDS_HOST"
195	          }
196	        },
197	        {
198	          secretKey = "NOWRDS_PORT"
199	          remoteRef = {
200	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
201	            property = "NOWRDS_PORT"
202	          }
203	        },
204	        {
205	          secretKey = "NOWRDS_USERNAME"
206	          remoteRef = {
207	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
208	            property = "NOWRDS_USERNAME"
209	          }
210	        },
211	        {
212	          secretKey = "NOWRDS_PASSWORD"
213	          remoteRef = {
214	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
215	            property = "NOWRDS_PASSWORD"
216	          }
217	        },
218	        {
219	          secretKey = "NOWRDS_INSTANCE_NAME"
220	          remoteRef = {
221	            key      = "saas/infrastructure/datadog-helper/${var.env}/${var.global_segment}"
222	            property = "NOWRDS_INSTANCE_NAME"
223	          }
224	        }
225	      ] : [])
226	    }
227	  }
228	  depends_on = [kubernetes_namespace.this]
229	}
230	# ---------------------------------------------------------------------------------------------------------------------
231	# DEPLOY A HELM CHART
232	# ---------------------------------------------------------------------------------------------------------------------
233	resource "helm_release" "this" {
234	  name      = var.name
235	  #namespace = kubernetes_namespace.this.metadata[0].name
236	  namespace = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
237	  wait      = false # Set to true if you want Terraform to wait for resources to be ready
238	
239	  repository = "https://helm.datadoghq.com"
240	  chart      = "datadog"
241	  version    = var.chart_version
242	  values = [
243	    templatefile("${path.module}/values.yaml.tftpl", {
244	      cluster_name   = var.cluster_name
245	      env            = var.env == "staging" ? "nonprod" : var.env
246	      global_segment = var.global_segment
247	      image_tag      = var.image_tag
248	      watch_namespace          = var.create_namespace ? kubernetes_namespace.this[0].metadata[0].name : var.namespace
249	      tags                     = concat(["global_segment:${var.global_segment}"], var.datadog_tags)
250	      agents_priority_class_name = var.agents_priority_class_name
251	
252	      apm_enabled = var.apm_enabled
253	
254	      container_exclude = var.container_exclude
255	      container_exclude_logs = var.container_exclude_logs
256	
257	      enable_mrds_monitoring   = var.enable_mrds_monitoring
258	      enable_nowrds_monitoring = var.enable_nowrds_monitoring
259	      enable_now_obfusicator_options = var.enable_now_obfusicator_options
260	      now_obfusicator_options = var.now_obfusicator_options
261	
262	      datadog_api_key_secret_name = var.datadog_api_key_secret_name
263	      cluster_agent_token_secret_name = var.cluster_agent_token_secret_name
264	      log_level = var.log_level
265	    })
266	  ]
267	
268	  depends_on = [
269	    kubernetes_namespace.this,
270	    kubernetes_manifest.external-secret,
271	    kubernetes_manifest.external-secret-dd-api-key,
272	    kubernetes_manifest.external-secret-dd-api-token
273	  ]
274	}
