276	module "netpol" {
277	  source = "git@gitlab.infrastructure.immuta.io:infrastructure/terraform/internal-modules/kubernetes/security/network-policy.git?ref=v1.1.0"
278	
279	  name             = join("-", [var.name, "netpol"])
280	  namespace        = var.namespace
281	  network_policies = local.netpols
282	
283	  tags = merge(var.tags, { "sourceModule" = "/internal-modules/kubernetes/monitoring/datadog" })
284	
285	  depends_on = [
286	    kubernetes_namespace.this
287	  ]
288	}
